  if(k!=='odonto'){let p=60+Math.floor(Rn()*30),ps=115+Math.floor(Rn()*30);const talla=150+Math.floor(Rn()*35);for(let j=4;j>=0;j--){h.sv.push({d:addDays(t0,-j*60-Math.floor(Rn()*10)),pas:ps+Math.floor(Rn()*12)-4,pad:70+Math.floor(Rn()*15),peso:Math.round((p+Rn()*3-1.5)*10)/10,talla,glu:85+Math.floor(Rn()*(h.riesgo.includes('Diabetes tipo 2')?70:25)),sat:95+Math.floor(Rn()*4)});}}
