function copago(){try{if(!pos.bcSrc||pos.medAdj===pos.bcSrc.turno)return;const t=bcTur(pos.bcSrc.turno);if(!t||!t.cust)return;const h=hc(t.cust);if(h.cob.os==='Particular'){pos.medAdj=t.id;return;}
 pos.lines.forEach(l=>{const p=prod(l.pid);if(!p||!p.svc||p.svc.tip)return;const c=cover(h.cob.os,p.id);if(!c.cov)return;l.price=c.pac;l.list=c.pac;l.name=p.name+' · copago '+h.cob.os+' (cubre '+money(c.cov)+')';});pos.medAdj=t.id;}catch(e){}}
