const consultorio=t=>{const E=bcBarbs(t.br);const i=E.findIndex(e=>e.id===t.barb);return cap0(RP().pu)+' '+(i+1);};
window.mdTV=()=>G().turnos.filter(t=>t.day===td()&&(t.st==='llam'||t.st==='atend')&&t.llamAt).sort((a,b)=>b.llamAt-a.llamAt).slice(0,6).map(t=>({n:String(t.name).split(' ')[0]+' '+String(t.name).split(' ').slice(1).join(' ').charAt(0)+'.',c:consultorio(t),p:bcBN(t.barb),ll:t.st==='llam'}));
A.msTV=()=>{const w=window.open('','vbsala');if(!w)return toast('Permití las ventanas emergentes para abrir la pantalla de la sala.',1);w.document.write(`<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Sala de espera · ${esc(S.tenant.name)}</title><style>body{margin:0;font-family:system-ui,sans-serif;background:#062c36;color:#fff}h1{margin:0;padding:24px 32px;background:#0e7490;font-size:34px}#l{padding:20px 32px}.r{display:flex;justify-content:space-between;align-items:center;padding:18px 22px;margin:12px 0;border-radius:16px;background:rgba(255,255,255,.08);font-size:40px}.r.n{background:#facc15;color:#111;animation:p 1s 3}.r small{font-size:24px;opacity:.8}@keyframes p{50%{transform:scale(1.03)}}</style></head><body><h1>${esc(S.tenant.name)} · Sala de espera</h1><div id="l"></div><script>function d(){try{var L=window.opener.mdTV();document.getElementById('l').innerHTML=L.length?L.map(function(x,i){return '<div class="r'+(x.ll&&i===0?' n':'')+'"><span>'+x.n+'<br><small>'+x.p+'</small></span><b>'+x.c+'</b></div>'}).join(''):'<p style="font-size:30px;opacity:.7">En breve te llamamos. ¡Gracias por esperar!</p>'}catch(e){}}d();setInterval(d,3000);<\/script></body></html>`);w.document.close();};
A.msSob=()=>{if(!(can('config')||(user&&user.role==='supervisor')))return toast('El sobrecupo lo autoriza un encargado o el profesional. Pedí que lo carguen ellos.',1);const C=(S.customers||[]).filter(c=>c.bc).slice().sort((a,b)=>nm(a).localeCompare(nm(b),'es'));
 modal('Sobrecupo de hoy',`<p class="sm mut">Se suma ahora mismo a la sala de espera, aunque la agenda del profesional esté completa. Queda registrado quién lo autorizó.</p><div class="grid g2"><div><label for="sc-c">Paciente</label><select id="sc-c">${C.map(c=>`<option value="${c.id}">${esc(nm(c))}</option>`).join('')}</select></div><div><label for="sc-p">${esc(cap0(RP().pro))}</label><select id="sc-p">${bcBarbs().map(e=>`<option value="${e.id}">${esc(bcBN(e.id))} · ${esc(bcBr(e.bc.br).short)}</option>`).join('')}</select></div></div><label for="sc-m">Motivo</label><input id="sc-m" placeholder="Ej.: fiebre alta, dolor agudo">`,{okText:'Agregar a la sala',onOk:w=>{const c=custOf(val('sc-c')),e=bcEmp(val('sc-p'));if(!c||!e)return false;if(val('sc-m').trim().length<3){w._err('Escribí el motivo del sobrecupo.');return false;}
  const sv=BC_SVC[7][0];const t=bcNewTurno({br:e.bc.br,barb:e.id,day:td(),t:Math.max(BC_OPEN,Math.floor(bcNowMin()/5)*5),svcs:[sv],name:nm(c),tel:c.wa,cust:c.id,origin:'mostrador',note:'Sobrecupo: '+val('sc-m').trim(),st:'conf',by:user?user.name:''});t.tipo='Sobrecupo';bcLog(t,'llego');
  audit('SOBRECUPO','#'+t.n+' · '+nm(c)+' · autorizó '+(user?user.name:''));save();rerender();toast('Sobrecupo agregado a la sala.');}});};
A.msFin=el=>{const t=bcTur(el.dataset.id);if(!t)return;const c=custOf(t.cust);
 modal('Finalizar atención · '+t.name,`<label for="mf-mot">Motivo de consulta</label><input id="mf-mot" value="${esc(t.note||'')}"><label for="mf-ev">Evolución</label><textarea id="mf-ev" rows="4" placeholder="Examen, diagnóstico, indicaciones"></textarea><label for="mf-dx">Diagnóstico (opcional)</label><input id="mf-dx">
 <p class="sm mut">La evolución queda firmada por ${esc(bcBN(t.barb))} con fecha y hora. Se descuentan los insumos de la práctica y el turno pasa a «Pendiente de cobro».</p>`,{wide:true,okText:'Firmar y finalizar',onOk:w=>{const ev=val('mf-ev').trim();if(ev.length<5){w._err('Escribí la evolución.');return false;}
  if(c){const h=hc(c.id);const i=svIdx(t.svcs[0]);h.ev.push({id:uid(),d:td(),ts:now(),prof:bcBN(t.barb),esp:RK()==='clinica'?ESP_SVC[i]||'':(bcEmp(t.barb)||{bc:{}}).bc.esp,motivo:val('mf-mot').trim(),txt:ev,dx:val('mf-dx').trim(),firm:true});h.ult=td();}
  try{if(window.bcConsume)bcConsume(t);}catch(e){}t.fin=true;audit('ATENCION_FINALIZADA','#'+t.n+' · evolución firmada');save();rerender();toast('Evolución firmada. Queda pendiente de cobro.');}});};

