let HQ='',HT='res';
reg('mdhce','Historias clínicas','agenda','bc_agenda',()=>{ensureMed();const q=bcNorm(HQ);const s=ST();
 const C=(S.customers||[]).filter(c=>c.bc&&(!q||bcNorm(nm(c)).includes(q)||String(c.dni||'').includes(q))).map(c=>({c,h:hc(c.id)})).sort((a,b)=>(b.h.ev.slice(-1)[0]||{d:''}).d.localeCompare((a.h.ev.slice(-1)[0]||{d:''}).d)).slice(0,60);
 const rec=recalls();
 return `<div class="row" style="flex-wrap:wrap;gap:.4rem;align-items:center"><h1 class="sp">Historias clínicas</h1><input id="hq" placeholder="Buscar por nombre o DNI" value="${esc(HQ)}" style="max-width:260px" aria-label="Buscar paciente"></div>
 <p class="sm mut">Una historia por paciente con alertas fijas arriba, antecedentes, medicación, evoluciones firmadas, ${RK()==='odonto'?'odontograma por pieza y cara':RK()==='clinica'?'resumen por especialidad':'signos vitales con series'}, recetas, órdenes, certificados, adjuntos y consentimientos.</p>
 ${rec.length?`<div class="card" style="margin-bottom:.6rem"><h3 style="margin-top:0">Seguimientos y recalls <span class="tag warn">${rec.length}</span></h3><div class="tw"><table><tbody>${rec.slice(0,12).map(r=>`<tr><td><b>${esc(nm(r.c))}</b><div class="sm mut">${esc(r.why)}</div></td><td><span class="tag">${esc(r.k)}</span></td><td class="r">${B.waB(r.c,'recall-'+r.k,r.msg,'WhatsApp')} <button class="btn sm" data-act="hcOpen" data-id="${r.c.id}">Historia</button></td></tr>`).join('')}</tbody></table></div></div>`:''}
 <div class="tw"><table><thead><tr><th>Paciente</th><th>Edad</th><th>Cobertura</th><th>Alertas</th><th>Última evolución</th><th></th></tr></thead><tbody>${C.map(({c,h})=>{const l=h.ev.slice().sort((a,b)=>a.d.localeCompare(b.d)).pop();
  return`<tr><td><b>${esc(nm(c))}</b><div class="sm mut">DNI ${esc(c.dni||'—')}</div></td><td>${ageOf(c.birth)??'—'}</td><td>${esc(h.cob.os)}${h.cob.os!=='Particular'?'<div class="sm mut">'+esc(h.cob.plan)+'</div>':''}</td><td>${h.alerg.map(a=>`<span class="tag bad">Alergia: ${esc(a)}</span>`).join(' ')} ${h.riesgo.map(a=>`<span class="tag warn">${esc(a)}</span>`).join(' ')}</td><td class="sm">${l?dmyX(l.d)+' · '+esc(l.prof)+'<div class="mut">'+esc(l.motivo)+'</div>':'—'}</td><td class="r"><button class="btn sm gold" data-act="hcOpen" data-id="${c.id}">Abrir</button></td></tr>`;}).join('')}</tbody></table></div>`;},null,'Barbería');
document.addEventListener('input',e=>{if(e.target&&e.target.id==='hq'){HQ=e.target.value;clearTimeout(window._hq);window._hq=setTimeout(()=>{rerender();setTimeout(()=>{const x=$('#hq');if(x){x.focus();x.setSelectionRange(x.value.length,x.value.length);}},30);},350);}});
function recalls(){const k=RK(),P=RP(),t0=td(),L=[];const s=ST();
 (S.customers||[]).filter(c=>c.bc).forEach(c=>{const h=hc(c.id);if(h.ult&&gD(h.ult,t0)>=P.ciclo&&gD(h.ult,t0)<=P.ciclo+120&&!G().turnos.some(t=>t.cust===c.id&&t.day>=t0))L.push({c,k:k==='odonto'?'Control semestral':'Chequeo anual',why:'Último control: '+dmyX(h.ult),msg:`Hola ${cN(c)}! Te escribimos de ${S.tenant.name}: ya te toca ${k==='odonto'?'el control odontológico de cada 6 meses':'tu chequeo anual'}. ¿Te reservamos un turno?`});
  h.docs.filter(d=>d.tipo==='Orden'&&d.pend).forEach(d=>L.push({c,k:'Resultados',why:'Orden del '+dmyX(d.d)+': '+d.txt,msg:`Hola ${cN(c)}! Cuando tengas los resultados de ${d.txt.toLowerCase()}, pedí un turno de control para que los vea tu médico. ${S.tenant.name}`}));});
 (s.planes||[]).forEach(p=>{const c=custOf(p.cust);if(!c)return;const pend=p.items.filter(i=>i.estado==='Aprobado'||i.estado==='En curso');if(pend.length&&!G().turnos.some(t=>t.cust===c.id&&t.day>=t0))L.push({c,k:'Tratamiento incompleto',why:pend.length+' prestación(es) aprobada(s) sin turno',msg:`Hola ${cN(c)}! Te quedan ${pend.length} prestaciones de tu tratamiento. ¿Coordinamos el próximo turno? ${S.tenant.name}`});});
 return L;}
