 const head=`<div class="card" style="padding:.6rem .8rem;border:2px solid ${h.alerg.length||h.riesgo.length?'#c0392b':'var(--line,#ddd)'};margin-bottom:.6rem"><div class="row" style="gap:.5rem;flex-wrap:wrap;align-items:center"><b>${esc(nm(c))}</b><span class="sm">${ageOf(c.birth)??'—'} años · DNI ${esc(c.dni||'—')}</span><span class="tag ${h.cob.os==='Particular'?'':'ok'}">${esc(h.cob.os)}${h.cob.os!=='Particular'?' '+esc(h.cob.plan)+' · '+esc(h.cob.afil):''}</span></div>
  <div style="margin-top:.35rem">${h.alerg.length?h.alerg.map(a=>`<span class="tag bad">⛔ Alergia: ${esc(a)}</span>`).join(' '):'<span class="sm mut">Sin alergias registradas</span>'} ${h.riesgo.map(a=>`<span class="tag warn">⚠ ${esc(a)}</span>`).join(' ')}${h.med.length?' <span class="sm">· Medicación: '+h.med.map(esc).join(', ')+'</span>':''}</div></div>
  <div class="row" style="gap:.3rem;flex-wrap:wrap;margin-bottom:.5rem">${T.map(([x,l])=>`<button type="button" class="btn sm ${HT===x?'gold':''}" data-ht="${x}">${l}</button>`).join('')}</div>`;
 let body='';
