  if(a==='saveRes'){h.cob={os:val('hc-os'),plan:val('hc-pl').trim(),afil:val('hc-af').trim()};h.alerg=sp(val('hc-al'));h.riesgo=sp(val('hc-rg'));h.med=sp(val('hc-md'));h.antP=val('hc-ap').trim();h.antF=val('hc-af2').trim();audit('HCE_DATOS',nm(c));save();toast('Datos guardados');hceOpen(cid);}
