  if(a==='saveSv'){const g=x=>parseFloat(String(val('sv-'+x)).replace(',','.'));const v={d:td(),pas:g('pas'),pad:g('pad'),peso:g('peso'),talla:g('talla'),glu:g('glu'),sat:g('sat')};if(isNaN(v.pas)||isNaN(v.pad))return toast('Cargá al menos la presión.',1);h.sv.push(v);audit('HCE_SIGNOS',nm(c));save();hceOpen(cid);}
