function spark(A,B2,u){if(!A.length)return'<p class="sm mut">Sin datos.</p>';const W=260,Hh=70,all=A.concat(B2||[]).filter(x=>!isNaN(x)),mn=Math.min(...all),mx=Math.max(...all),n=A.length;const P=L=>L.map((v,i)=>(8+i*(W-16)/Math.max(1,n-1)).toFixed(1)+','+(Hh-8-((v-mn)/Math.max(1,mx-mn))*(Hh-20)).toFixed(1)).join(' ');
 return`<svg viewBox="0 0 ${W} ${Hh}" style="width:100%;max-width:${W}px" role="img" aria-label="Serie de ${u}"><polyline points="${P(A)}" fill="none" stroke="var(--gold)" stroke-width="2.5"/>${B2?`<polyline points="${P(B2)}" fill="none" stroke="#94a3b8" stroke-width="2"/>`:''}<text x="${W-4}" y="12" text-anchor="end" font-size="11" fill="currentColor">${A[n-1]}${B2?'/'+B2[n-1]:''} ${u}</text></svg>`;}
function printDoc(c,d){const x=window.open('','_blank');if(!x)return toast('Permití las ventanas emergentes para imprimir.',1);const h=hc(c.id);
 x.document.write(`<!doctype html><title>${esc(d.tipo)}</title><body style="font-family:Georgia,serif;padding:32px;max-width:640px;margin:auto"><h2 style="margin:0">${esc(S.tenant.name)}</h2><div style="color:#555">${esc(S.tenant.address||'')}</div><hr><p><b>${esc(d.tipo)}</b> · ${dmyX(d.d)}</p><p>Paciente: <b>${esc(nm(c))}</b> · DNI ${esc(c.dni||'')}<br>Cobertura: ${esc(h.cob.os)} ${esc(h.cob.plan)} ${esc(h.cob.afil)}</p>
 <div style="font-size:1.15rem;white-space:pre-wrap;margin:24px 0;min-height:180px">${d.tipo==='Receta'?'Rp/ ':''}${esc(d.txt)}</div><div style="text-align:right;margin-top:60px">__________________________<br>${esc(d.prof)}<br><small>Firma y sello</small></div><p style="color:#888;font-size:12px;margin-top:40px">Documento de ejemplo · demo Sistema VB</p></body>`);x.document.close();setTimeout(()=>x.print(),300);}
/* ---------- odontograma ---------- */
function TEETH(){const U=[18,17,16,15,14,13,12,11,21,22,23,24,25,26,27,28],L=[48,47,46,45,44,43,42,41,31,32,33,34,35,36,37,38];return U.concat(L).map(String);}
const OC={c:['#ef4444','Caries (preexistente)'],r:['#3b82f6','Restauración (preexistente)'],i:['#f59e0b','Prestación indicada'],h:['#22c55e','Realizada']};
function odoHTML(h){const s=34,g=6;const U=[18,17,16,15,14,13,12,11,21,22,23,24,25,26,27,28],L=[48,47,46,45,44,43,42,41,31,32,33,34,35,36,37,38];
 const tooth=(pz,x,y,up)=>{const o=h.odo[pz]||{f:{},t:''};const fc=f=>o.f[f]?OC[o.f[f]][0]:'#fff';const left=(+String(pz)[0]===1||+String(pz)[0]===4)?'D':'M',right=left==='D'?'M':'D';const top=up?'V':'L',bot=up?'L':'V';
  const P=(pts,f)=>`<polygon points="${pts.map(p=>p.join(',')).join(' ')}" fill="${fc(f)}" stroke="#334155" stroke-width="1" data-pz="${pz}" data-f="${f}" style="cursor:pointer"><title>Pieza ${pz} · cara ${({O:'oclusal',V:'vestibular',L:up?'palatina':'lingual',M:'mesial',D:'distal'})[f]}</title></polygon>`;
  const a=.3*s,b=.7*s;return`<g>${P([[x,y],[x+s,y],[x+b,y+a],[x+a,y+a]],top)}${P([[x,y+s],[x+s,y+s],[x+b,y+b],[x+a,y+b]],bot)}${P([[x,y],[x+a,y+a],[x+a,y+b],[x,y+s]],left)}${P([[x+s,y],[x+b,y+a],[x+b,y+b],[x+s,y+s]],right)}${P([[x+a,y+a],[x+b,y+a],[x+b,y+b],[x+a,y+b]],'O')}
  ${o.t==='aus'?`<line x1="${x}" y1="${y}" x2="${x+s}" y2="${y+s}" stroke="#64748b" stroke-width="3"/><line x1="${x+s}" y1="${y}" x2="${x}" y2="${y+s}" stroke="#64748b" stroke-width="3"/>`:o.t==='ext'?`<line x1="${x}" y1="${y}" x2="${x+s}" y2="${y+s}" stroke="#ef4444" stroke-width="3"/><line x1="${x+s}" y1="${y}" x2="${x}" y2="${y+s}" stroke="#ef4444" stroke-width="3"/>`:''}
  <text x="${x+s/2}" y="${up?y-4:y+s+13}" text-anchor="middle" font-size="11" fill="currentColor" data-pz="${pz}" data-f="T" style="cursor:pointer">${pz}</text></g>`;};
 const W=16*(s+g)+g*3;let svg=`<svg viewBox="0 0 ${W} ${2*s+70}" style="width:100%;max-width:760px" role="img" aria-label="Odontograma">`;
 U.forEach((pz,i)=>{svg+=tooth(pz,g+i*(s+g)+(i>=8?g*2:0),18,true);});L.forEach((pz,i)=>{svg+=tooth(pz,g+i*(s+g)+(i>=8?g*2:0),18+s+22,false);});svg+='</svg>';
 const m=window._odm||'c';const btn=(k,l)=>`<button type="button" class="btn sm ${m===k?'gold':''}" data-hc="odoMode" data-m="${k}">${l}</button>`;
 const ind=Object.keys(h.odo).filter(pz=>Object.values(h.odo[pz].f).includes('i')||h.odo[pz].t==='ext').length;
 return`<p class="sm mut">Elegí qué marcar y tocá la cara de la pieza (o el número para la pieza entera). Rojo y azul son preexistencias; naranja, lo indicado; verde, lo realizado.</p><div class="row" style="gap:.3rem;flex-wrap:wrap;margin-bottom:.4rem">${btn('c','🔴 Caries')}${btn('r','🔵 Restauración')}${btn('i','🟠 Indicada')}${btn('h','🟢 Realizada')}${btn('aus','✖ Ausente')}${btn('ext','✖ Extracción indicada')}${btn('x','Borrar')}</div>${svg}
 <div class="row" style="gap:.4rem;align-items:center;margin-top:.4rem"><span class="sm">${ind} pieza(s) con prestaciones indicadas</span><button type="button" class="btn sm gold" data-hc="odoPlan" ${ind?'':'disabled'}>Pasar lo indicado al plan y presupuesto</button></div>`;}
function odoClick(h,pz,f,w){const m=window._odm||'c';const o=h.odo[pz]=h.odo[pz]||{f:{},t:''};
 if(f==='T'||m==='aus'||m==='ext'){o.t=m==='aus'||m==='ext'?(o.t===m?'':m):m==='x'?'':o.t;if(m==='x')o.f={};}else{if(m==='x')delete o.f[f];else o.f[f]=m;}
 audit('ODONTOGRAMA','pieza '+pz+(f!=='T'?' cara '+f:'')+' · '+m);const c=Object.keys(H()).find(k=>H()[k]===h);if(c)hceOpen(c,'odo');}
function odoPlan(c,h){const s=ST();s.planes=s.planes||[];let p=s.planes.find(x=>x.cust===c.id&&x.items.some(i=>i.estado!=='Realizado'));if(!p){p={id:uid(),cust:c.id,tit:'Plan de tratamiento odontológico',d:td(),cuotas:1,pag:[],items:[]};s.planes.push(p);}let n=0;
 Object.keys(h.odo).forEach(pz=>{const o=h.odo[pz];const car=Object.keys(o.f).filter(f=>o.f[f]==='i');const add=(svc,caras)=>{if(p.items.some(i=>i.pieza===pz&&i.svc===svc&&i.estado!=='Realizado'))return;p.items.push({id:uid(),svc,pieza:pz,caras,estado:'Presupuestado'});n++;};
  if(car.length)add(BC_SVC[2][0],car.join(''));if(o.t==='ext')add(BC_SVC[4][0],'');});
 audit('PLAN_DESDE_ODONTOGRAMA',nm(c)+' · '+n+' ítem(s)');save();toast(n?n+' prestación(es) agregadas al plan':'Ya estaban en el plan');$$('#modal-root .ov').forEach(o=>o.remove());go('mdplan');setTimeout(()=>A.plOpen({dataset:{id:p.id}}),200);}

