const PST=['Presupuestado','Aprobado','En curso','Realizado'];
function plTot(p){const h=hc(p.cust);return p.items.reduce((a,i)=>{const c=cover(h.cob.os,i.svc);a.tot+=c.tot;a.cov+=c.cov;a.pac+=c.pac;if(i.estado==='Realizado')a.hecho+=c.tot;return a;},{tot:0,cov:0,pac:0,hecho:0});}
reg('mdplan','Planes y presupuestos','agenda','bc_agenda',()=>{ensureMed();const s=ST();const L=(s.planes||[]).slice().sort((a,b)=>b.d.localeCompare(a.d));const pend=L.reduce((a,p)=>a+p.items.filter(i=>i.estado==='Presupuestado').length,0);
 return `<div class="row" style="flex-wrap:wrap;gap:.4rem;align-items:center"><h1 class="sp">Planes y presupuestos</h1><button class="btn gold" data-act="plNew">+ Nuevo plan</button></div>
 <p class="sm mut">Cada plan agrupa prácticas o sesiones con su estado (presupuestado, aprobado, en curso, realizado). Calcula lo que cubre la obra social y el saldo del paciente, y admite cuotas y entregas.</p>
 <div class="grid g3" style="margin:.5rem 0"><div class="card kpi"><span>Planes</span><b>${L.length}</b><span>${L.filter(p=>p.items.some(i=>i.estado!=='Realizado')).length} abiertos</span></div><div class="card kpi"><span>Ítems sin aprobar</span><b>${pend}</b><span>presupuestos pendientes</span></div><div class="card kpi"><span>A cargo de pacientes</span><b>${money(L.reduce((a,p)=>a+plTot(p).pac,0))}</b><span>${money(L.reduce((a,p)=>a+(p.pag||[]).reduce((x,y)=>x+y.amt,0),0))} cobrado</span></div></div>
 <div class="tw"><table data-bulk="mdpl"><thead><tr><th>Paciente</th><th>Plan</th><th>Avance</th><th class="r">Total</th><th class="r">Cubre</th><th class="r">Paciente</th><th></th></tr></thead><tbody>${L.map(p=>{const c=custOf(p.cust),t=plTot(p),d=p.items.filter(i=>i.estado==='Realizado').length;
  return`<tr data-id="${p.id}"><td><b>${esc(nm(c))}</b><div class="sm mut">${esc(hc(p.cust).cob.os)}</div></td><td>${esc(p.tit)}<div class="sm mut">${dmyX(p.d)} · ${p.items.length} ítem(s)</div></td><td><span class="tag ${d===p.items.length?'ok':p.items.some(i=>i.estado==='Presupuestado')?'warn':''}">${d}/${p.items.length}</span></td><td class="r">${money(t.tot)}</td><td class="r">${money(t.cov)}</td><td class="r"><b>${money(t.pac)}</b></td><td class="r"><button class="btn sm gold" data-act="plOpen" data-id="${p.id}">Abrir</button></td></tr>`;}).join('')||'<tr><td class="mut">Sin planes.</td></tr>'}</tbody></table></div>`;},null,'Barbería');
try{if(window.VB_BULK)VB_BULK.mdpl={can:()=>can('config'),del:ids=>vbRemove({get:()=>ST().planes,ids,label:ids.length+' plan(es) borrado(s)',audit:'PLAN_BORRADO'})};}catch(e){}
A.plNew=()=>{const C=(S.customers||[]).filter(c=>c.bc).slice().sort((a,b)=>nm(a).localeCompare(nm(b),'es'));modal('Nuevo plan',`<div class="grid g2"><div><label for="pn-c">Paciente</label><select id="pn-c">${C.map(c=>`<option value="${c.id}">${esc(nm(c))}</option>`).join('')}</select></div><div><label for="pn-t">Nombre del plan</label><input id="pn-t" value="${RK()==='odonto'?'Plan de tratamiento odontológico':'Plan de tratamiento'}"></div></div>`,{okText:'Crear',onOk:()=>{const p={id:uid(),cust:val('pn-c'),tit:val('pn-t').trim()||'Plan',d:td(),cuotas:1,pag:[],items:[]};(ST().planes=ST().planes||[]).push(p);save();setTimeout(()=>A.plOpen({dataset:{id:p.id}}),50);}});};
A.plOpen=el=>{const p=(ST().planes||[]).find(x=>x.id===el.dataset.id);if(!p)return;const c=custOf(p.cust),h=hc(p.cust),t=plTot(p);const pag=(p.pag||[]).reduce((a,x)=>a+x.amt,0);
 const w=modal(p.tit+' · '+nm(c),`<p class="sm">Cobertura: <b>${esc(h.cob.os)}</b>${cobOf(h.cob.os)[1]?' · cubre '+cobOf(h.cob.os)[1]+' %':''}${cobOf(h.cob.os)[2]?' · pide autorización para prácticas':''}</p>
 <div class="tw"><table><thead><tr><th>Práctica</th><th>Pieza</th><th>Estado</th><th class="r">Arancel</th><th class="r">Cubre</th><th class="r">Paciente</th><th></th></tr></thead><tbody>${p.items.map(i=>{const pr=prod(i.svc),cv=cover(h.cob.os,i.svc);return`<tr><td>${esc(pr?pr.name:'')}</td><td>${esc(i.pieza||'—')}${i.caras?' · '+esc(i.caras):''}</td><td><select class="pl-st" data-i="${i.id}" aria-label="Estado">${PST.map(x=>`<option${i.estado===x?' selected':''}>${x}</option>`).join('')}</select></td><td class="r">${money(cv.tot)}</td><td class="r">${money(cv.cov)}${cv.auth?'<div class="sm mut">con autorización</div>':''}</td><td class="r">${money(cv.pac)}</td><td><button type="button" class="btn sm vb-ib" data-pl="del" data-i="${i.id}" aria-label="Quitar">✕</button></td></tr>`;}).join('')}</tbody>
 <tfoot><tr><td colspan="3"><b>Totales</b></td><td class="r"><b>${money(t.tot)}</b></td><td class="r">${money(t.cov)}</td><td class="r"><b>${money(t.pac)}</b></td><td></td></tr></tfoot></table></div>
 <div class="grid g3"><div><label for="pl-sv">Agregar práctica</label><select id="pl-sv">${BC_SVC.map(sv=>{const pr=prod(sv[0]);return pr?`<option value="${pr.id}">${esc(pr.name)}</option>`:'';}).join('')}</select></div>${RK()==='odonto'?'<div><label for="pl-pz">Pieza</label><input id="pl-pz" placeholder="Ej.: 36"></div>':''}<div style="align-self:end"><button type="button" class="btn sm" data-pl="add">+ Agregar</button></div></div>
 <div class="grid g3" style="margin-top:.5rem"><div><label for="pl-cu">Cuotas</label><input id="pl-cu" type="number" min="1" max="12" value="${p.cuotas||1}"></div><div><label>Pagado</label><p><b>${money(pag)}</b> de ${money(t.pac)} · ${p.cuotas>1?'cuota '+money(Math.round(t.pac/p.cuotas)):'pago único'}</p></div><div style="align-self:end"><button type="button" class="btn sm" data-pl="ap">Aprobar todo</button> <button type="button" class="btn sm" data-pl="print">Imprimir presupuesto</button>${c&&c.wa?` <a class="btn sm" target="_blank" rel="noopener" href="${esc(waTo(c.wa,`Hola ${cN(c)}! Te pasamos el presupuesto de ${S.tenant.name}:\n`+p.items.map(i=>'• '+(prod(i.svc)||{}).name+(i.pieza?' (pieza '+i.pieza+')':'')+': '+money(cover(h.cob.os,i.svc).pac)).join('\n')+`\nTotal a tu cargo: ${money(t.pac)}${p.cuotas>1?' en '+p.cuotas+' cuotas de '+money(Math.round(t.pac/p.cuotas)):''}. Respondé OK para aprobarlo.`))}">💬 Enviar</a>`:''}</div></div>`,{wide:true,okText:'Guardar',onOk:()=>{p.cuotas=Math.max(1,parseInt(val('pl-cu'),10)||1);$$('.pl-st').forEach(x=>{const i=p.items.find(y=>y.id===x.dataset.i);if(i&&i.estado!==x.value){i.estado=x.value;if(x.value==='Realizado'&&i.pieza){const o=hc(p.cust).odo[i.pieza];if(o){Object.keys(o.f).forEach(f=>{if(o.f[f]==='i')o.f[f]='h';});if(o.t==='ext')o.t='aus';}}}});audit('PLAN_GUARDADO',nm(c));save();rerender();}});
 w.addEventListener('click',e=>{const b=e.target.closest('[data-pl]');if(!b)return;const a=b.dataset.pl;
  if(a==='add'){p.items.push({id:uid(),svc:val('pl-sv'),pieza:(val('pl-pz')||'').trim(),caras:'',estado:'Presupuestado'});save();w.remove();A.plOpen({dataset:{id:p.id}});}
  if(a==='del'){p.items=p.items.filter(i=>i.id!==b.dataset.i);save();w.remove();A.plOpen({dataset:{id:p.id}});}
  if(a==='ap'){p.items.forEach(i=>{if(i.estado==='Presupuestado')i.estado='Aprobado';});audit('PLAN_APROBADO',nm(c));save();w.remove();A.plOpen({dataset:{id:p.id}});}
  if(a==='print'){const x=window.open('','_blank');if(!x)return toast('Permití las ventanas emergentes para imprimir.',1);x.document.write(`<!doctype html><title>Presupuesto</title><body style="font-family:sans-serif;padding:28px;max-width:720px;margin:auto"><h2>${esc(S.tenant.name)} · Presupuesto</h2><p>${esc(nm(c))} · ${esc(h.cob.os)} · ${dmyX(td())}</p><table style="width:100%;border-collapse:collapse" border="1" cellpadding="6"><tr><th>Práctica</th><th>Pieza</th><th>Arancel</th><th>Cubre</th><th>Paciente</th></tr>${p.items.map(i=>{const cv=cover(h.cob.os,i.svc);return`<tr><td>${esc((prod(i.svc)||{}).name)}</td><td>${esc(i.pieza||'')}</td><td>${money(cv.tot)}</td><td>${money(cv.cov)}</td><td>${money(cv.pac)}</td></tr>`;}).join('')}<tr><td colspan="4"><b>Total a cargo del paciente</b></td><td><b>${money(t.pac)}</b></td></tr></table><p>${p.cuotas>1?p.cuotas+' cuotas de '+money(Math.round(t.pac/p.cuotas)):'Pago único'} · Validez 30 días.</p><p style="color:#888;font-size:12px">Documento de ejemplo · demo Sistema VB</p></body>`);x.document.close();setTimeout(()=>x.print(),300);}});};

/* =====================================================================
   COBERTURAS: nomenclador, prestaciones por período y autorizaciones
   ===================================================================== */
let CTB='nom';
reg('mdcob','Coberturas','money2','bc_rank',()=>{ensureMed();const s=ST();const T=[['nom','Nomenclador'],['pres','Prestaciones a coberturas'],['aut','Autorizaciones']];
 const bar=`<div class="row" style="flex-wrap:wrap;gap:.4rem"><h1 class="sp">Coberturas</h1>${T.map(([k,l])=>`<button class="btn sm ${CTB===k?'gold':''}" data-act="cbTab" data-t="${k}">${l}</button>`).join('')}</div>`;
 if(CTB==='nom')return bar+`<p class="sm mut" style="margin:.5rem 0">Arancel particular y lo que cubre cada obra social o prepaga; el resto es el copago del paciente. Al cobrar un turno en Vender se cobra sólo el copago.</p><div class="tw"><table><thead><tr><th>Práctica</th><th class="r">Particular</th>${COB.slice(0,5).map(c=>`<th class="r">${c[0]}<div class="sm mut">${c[1]} %${c[2]?' · aut.':''}</div></th>`).join('')}</tr></thead><tbody>${BC_SVC.map(sv=>{const p=prod(sv[0]);if(!p)return'';return`<tr><td><b>${esc(p.name)}</b>${isPract(svIdx(p.id))?' <span class="tag">Práctica</span>':''}${(EXCL[RK()]||[]).includes(svIdx(p.id))?' <span class="tag bad">Sin cobertura</span>':''}</td><td class="r">${money(p.price)}</td>${COB.slice(0,5).map(c=>{const v=cover(c[0],p.id);return`<td class="r">${money(v.cov)}<div class="sm mut">copago ${money(v.pac)}</div></td>`;}).join('')}</tr>`;}).join('')}</tbody></table></div>`;
 if(CTB==='aut'){const L=(s.prest||[]).filter(p=>p.auth!=='—').sort((a,b)=>(a.auth==='pendiente'?0:1)-(b.auth==='pendiente'?0:1)||b.d.localeCompare(a.d));
  return bar+`<p class="sm mut" style="margin:.5rem 0">Prácticas que la cobertura autoriza antes (IOSFA y PAMI en esta demo).</p><div class="tw"><table><tbody>${L.slice(0,60).map(p=>`<tr><td><b>${esc(nm(custOf(p.cust)))}</b><div class="sm mut">${dmyX(p.d)} · ${esc((prod(p.svc)||{}).name||'')}</div></td><td>${esc(p.cob)}</td><td>${p.auth==='aprobada'?'<span class="tag ok">Autorizada</span>':p.auth==='rechazada'?'<span class="tag bad">Rechazada</span>':'<span class="tag warn">Pendiente</span>'}</td><td class="r">${p.auth==='pendiente'?`<button class="btn sm gold" data-act="cbAut" data-id="${p.id}" data-v="aprobada">Autorizada</button> <button class="btn sm" data-act="cbAut" data-id="${p.id}" data-v="rechazada">Rechazada</button>`:''}</td></tr>`).join('')||'<tr><td class="mut">Sin autorizaciones.</td></tr>'}</tbody></table></div>`;}
 const L=(s.prest||[]).filter(p=>p.cob!=='Particular');const G0={};L.forEach(p=>{const k=p.cob+'|'+p.d.slice(0,7);(G0[k]=G0[k]||[]).push(p);});
 const EST={pendiente:['Sin presentar','warn'],presentada:['Presentada',''],pagada:['Pagada','ok'],debito:['Débito','bad']};
 return bar+`<p class="sm mut" style="margin:.5rem 0">Prestaciones realizadas agrupadas por cobertura y mes: se presentan, se registra el pago y se controlan los débitos o rechazos.</p><div class="tw"><table><thead><tr><th>Cobertura · período</th><th class="r">Prestaciones</th><th class="r">A cobrar</th><th>Estado</th><th class="r">Débitos</th><th></th></tr></thead><tbody>${Object.keys(G0).sort().reverse().map(k=>{const P=G0[k],[os,mes]=k.split('|');const cnt={};P.forEach(p=>cnt[p.est]=(cnt[p.est]||0)+1);const deb=P.filter(p=>p.est==='debito');
  return`<tr><td><b>${esc(os)}</b><div class="sm mut">${mes.split('-').reverse().join('/')}</div></td><td class="r">${P.length}</td><td class="r">${money(P.reduce((a,p)=>a+p.cov,0))}</td><td>${Object.keys(cnt).map(e=>`<span class="tag ${EST[e]?EST[e][1]:''}">${EST[e]?EST[e][0]:e} ${cnt[e]}</span>`).join(' ')}</td><td class="r">${deb.length?money(deb.reduce((a,p)=>a+p.cov,0)):'—'}</td>
  <td class="r">${cnt.pendiente?`<button class="btn sm gold" data-act="cbPres" data-k="${esc(k)}">Presentar</button>`:''} ${cnt.presentada?`<button class="btn sm" data-act="cbPago" data-k="${esc(k)}">Registrar pago</button>`:''} <button class="btn sm" data-act="cbDet" data-k="${esc(k)}">Detalle</button></td></tr>`;}).join('')||'<tr><td class="mut">Sin prestaciones.</td></tr>'}</tbody></table></div>`;},null,'Barbería');
A.cbTab=el=>{CTB=el.dataset.t;rerender();};
const grp=k=>{const [os,mes]=k.split('|');return(ST().prest||[]).filter(p=>p.cob===os&&p.d.slice(0,7)===mes);};
A.cbPres=el=>{const P=grp(el.dataset.k).filter(p=>p.est==='pendiente');P.forEach(p=>p.est='presentada');audit('LIQUIDACION_PRESENTADA',el.dataset.k+' · '+P.length);save();rerender();toast(P.length+' prestación(es) presentada(s)');};
A.cbPago=el=>{const P=grp(el.dataset.k).filter(p=>p.est==='presentada');modal('Registrar pago · '+el.dataset.k.replace('|',' · '),`<p class="sm">Marcá las que la cobertura <b>no</b> pagó (quedan como débito).</p>${P.map(p=>`<label class="chk"><input type="checkbox" class="cb-deb" value="${p.id}"> ${esc(nm(custOf(p.cust)))} · ${esc((prod(p.svc)||{}).name||'')} · ${money(p.cov)}</label>`).join('')}<label for="cb-mot">Motivo de los débitos</label><input id="cb-mot" placeholder="Ej.: falta la orden médica">`,{okText:'Registrar',onOk:w=>{const D=new Set($$('.cb-deb:checked',w).map(x=>x.value));P.forEach(p=>{if(D.has(p.id)){p.est='debito';p.mot=val('cb-mot').trim()||'Sin motivo informado';}else p.est='pagada';});audit('LIQUIDACION_PAGO',el.dataset.k+' · '+(P.length-D.size)+' pagadas, '+D.size+' débitos');save();rerender();}});};
A.cbDet=el=>{const P=grp(el.dataset.k);modal('Detalle · '+el.dataset.k.replace('|',' · '),`<div class="tw"><table><thead><tr><th>Fecha</th><th>Paciente</th><th>Práctica</th><th>${esc(cap0(RP().pro))}</th><th class="r">Cubre</th><th>Estado</th></tr></thead><tbody>${P.map(p=>`<tr><td>${dmyX(p.d)}</td><td>${esc(nm(custOf(p.cust)))}</td><td>${esc((prod(p.svc)||{}).name||'')}</td><td>${esc(bcBN(p.prof))}</td><td class="r">${money(p.cov)}</td><td>${esc(p.est)}${p.mot?'<div class="sm mut">'+esc(p.mot)+'</div>':''}</td></tr>`).join('')}</tbody></table></div>`,{wide:true,ok:false,cancelText:'Cerrar'});};
A.cbAut=el=>{const p=(ST().prest||[]).find(x=>x.id===el.dataset.id);if(!p)return;p.auth=el.dataset.v;audit('AUTORIZACION',(prod(p.svc)||{}).name+' · '+p.auth);save();rerender();};

/* =====================================================================
   LIQUIDACIÓN DE PROFESIONALES
   ===================================================================== */
const LQ=()=>{const s=ST();if(!s.liq)s.liq={part:60,os:70,fijo:6000000};return s.liq;};
reg('mdliq','Liquidación de profesionales','money2','bc_barb',()=>{ensureMed();const q=LQ(),m=td().slice(0,8)+'01';const P=(ST().prest||[]).filter(p=>p.d>=m);
 const R0=bcBarbs().map(e=>{const L=P.filter(p=>p.prof===e.id);const part=L.filter(p=>p.cob==='Particular'),os=L.filter(p=>p.cob!=='Particular');
  const hp=part.reduce((a,p)=>a+p.tot,0)*q.part/100,dev=os.reduce((a,p)=>a+p.tot,0)*q.os/100,hab=os.filter(p=>p.est==='pagada').reduce((a,p)=>a+p.tot,0)*q.os/100;
  const ins=G().turnos.filter(t=>t.barb===e.id&&t.day>=m&&t.insCost).reduce((a,t)=>a+t.insCost,0);return{e,n:L.length,hp,dev,hab,ins,devT:hp+dev-q.fijo-ins,habT:hp+hab-q.fijo-ins};});
 return `<div class="row" style="flex-wrap:wrap;gap:.4rem;align-items:center"><h1 class="sp">Liquidación de profesionales</h1><button class="btn sm" data-act="lqCfg">Esquema</button></div>
 <p class="sm mut">Honorarios del mes: ${q.part} % del arancel particular y ${q.os} % de las prestaciones a coberturas, menos ${money(q.fijo)} por uso de ${esc(RP().pu)} e insumos pactados. «Devengado» es lo atendido; «habilitado» suma de las coberturas sólo lo que ya pagaron.</p>
 <div class="tw"><table><thead><tr><th>${esc(cap0(RP().pro))}</th><th class="r">Prestaciones</th><th class="r">Particular</th><th class="r">Coberturas</th><th class="r">Uso e insumos</th><th class="r">Devengado</th><th class="r">Habilitado</th></tr></thead><tbody>${R0.map(x=>`<tr><td><b>${esc(bcBN(x.e.id))}</b><div class="sm mut">${esc(x.e.bc.esp)}</div></td><td class="r">${x.n}</td><td class="r">${money(Math.round(x.hp))}</td><td class="r">${money(Math.round(x.dev))}</td><td class="r">−${money(Math.round(q.fijo+x.ins))}</td><td class="r">${money(Math.round(x.devT))}</td><td class="r"><b>${money(Math.round(x.habT))}</b></td></tr>`).join('')}</tbody>
 <tfoot><tr><td><b>Total</b></td><td class="r">${R0.reduce((a,x)=>a+x.n,0)}</td><td></td><td></td><td></td><td class="r"><b>${money(Math.round(R0.reduce((a,x)=>a+x.devT,0)))}</b></td><td class="r"><b>${money(Math.round(R0.reduce((a,x)=>a+x.habT,0)))}</b></td></tr></tfoot></table></div>`;},null,'Barbería');
A.lqCfg=()=>{const q=LQ();modal('Esquema de liquidación',`<div class="grid g3"><div><label for="lq-p">% sobre particular</label><input id="lq-p" type="number" min="0" max="100" value="${q.part}"></div><div><label for="lq-o">% sobre coberturas</label><input id="lq-o" type="number" min="0" max="100" value="${q.os}"></div><div><label for="lq-f">Uso de ${esc(RP().pu)} por mes ($)</label><input id="lq-f" inputmode="decimal" value="${q.fijo/100}"></div></div>`,{okText:'Guardar',onOk:()=>{q.part=Math.min(100,Math.max(0,+val('lq-p')||0));q.os=Math.min(100,Math.max(0,+val('lq-o')||0));q.fijo=Math.round((parseFloat(String(val('lq-f')).replace(/\./g,'').replace(',','.'))||0)*100);audit('LIQUIDACION_ESQUEMA',q.part+' % / '+q.os+' %');save();rerender();}});};

/* =====================================================================
   TABLERO GERENCIAL
   ===================================================================== */
reg('mddash','Tablero clínico','home','dashboard',()=>{ensureMed();const t0=td(),d30=addDays(t0,-30),d7=addDays(t0,-6);const T=G().turnos.filter(t=>t.day>=d30&&t.day<=t0&&t.st!=='cancel');
 const aus=T.filter(t=>t.st==='novino').length,at=T.filter(t=>t.st==='hecho').length;const E=bcBarbs();const slots=Math.floor((BC_CLOSE-BC_OPEN)/30);
 const occ=[];for(let i=6;i>=0;i--){const d=addDays(t0,-i);if(bcDow(d)===0)continue;const mins=G().turnos.filter(t=>t.day===d&&t.st!=='cancel').reduce((a,t)=>a+t.dur,0);occ.push([d.slice(8)+'/'+d.slice(5,7),Math.round(mins/(E.length*(BC_CLOSE-BC_OPEN))*100)]);}
 const P=(ST().prest||[]).filter(p=>p.d>=d30);const byC={};P.forEach(p=>{byC[p.cob]=(byC[p.cob]||0)+(p.cob==='Particular'?p.tot:p.cov);});const mx=Math.max(1,...Object.values(byC));
 const pend=(ST().planes||[]).reduce((a,p)=>a+p.items.filter(i=>i.estado==='Presupuestado').reduce((x,i)=>x+cover(hc(p.cust).cob.os,i.svc).pac,0),0);
 const deb=P.filter(p=>p.est==='debito').reduce((a,p)=>a+p.cov,0);
 const bar=(l,v,max,txt)=>`<div style="display:grid;grid-template-columns:120px 1fr 110px;gap:.5rem;align-items:center;margin:.25rem 0"><span class="sm">${esc(l)}</span><div style="background:rgba(127,127,127,.15);border-radius:6px;height:14px"><div style="width:${Math.min(100,Math.round(v/max*100))}%;height:14px;border-radius:6px;background:var(--gold)"></div></div><span class="sm r">${txt}</span></div>`;
 return `<div class="row" style="flex-wrap:wrap;gap:.4rem;align-items:center"><h1 class="sp">Tablero clínico</h1><button class="btn sm" data-act="nav" data-id="mdsala">Sala de espera</button></div>
 <div class="grid g4" style="margin:.5rem 0"><div class="card kpi"><span>Ocupación de agendas</span><b>${occ.length?Math.round(occ.reduce((a,x)=>a+x[1],0)/occ.length):0} %</b><span>promedio de la semana</span></div><div class="card kpi"><span>Ausentismo</span><b class="${aus/(at+aus||1)>.1?'g-bad':''}">${Math.round(aus/(at+aus||1)*100)} %</b><span>${aus} ausentes en 30 días</span></div><div class="card kpi"><span>Presupuestos sin aprobar</span><b>${money(pend)}</b><span>a cargo de pacientes</span></div><div class="card kpi"><span>Débitos de coberturas</span><b class="${deb?'g-bad':''}">${money(deb)}</b><span>últimos 30 días</span></div></div>
 <div class="grid g2"><div class="card"><h3 style="margin-top:0">Ocupación por día</h3>${occ.map(([d,v])=>bar(d,v,100,v+' %')).join('')}</div><div class="card"><h3 style="margin-top:0">Ingresos por cobertura (30 días)</h3>${Object.keys(byC).sort((a,b)=>byC[b]-byC[a]).map(k=>bar(k,byC[k],mx,money(byC[k]))).join('')||'<p class="mut">Sin datos.</p>'}</div></div>
 <div class="card" style="margin-top:.6rem"><h3 style="margin-top:0">Ocupación por ${esc(RP().pro)} hoy</h3>${E.map(e=>{const m=G().turnos.filter(t=>t.day===t0&&t.barb===e.id&&t.st!=='cancel').reduce((a,t)=>a+t.dur,0);return bar(bcBN(e.id),m,BC_CLOSE-BC_OPEN,Math.round(m/(BC_CLOSE-BC_OPEN)*100)+' %');}).join('')}</div>`;},null,'Barbería');

